<?php
namespace App\Controllers; use App\Core\{Controller,Database}; class DashboardController extends Controller{public function index(){ $db=Database::pdo();$stats=['funds'=>$db->query('SELECT COUNT(*) c FROM funds')->fetch()['c']??0,'members'=>$db->query('SELECT COUNT(*) c FROM users')->fetch()['c']??0,'unpaid'=>$db->query("SELECT COUNT(*) c FROM installments WHERE status IN('unpaid','overdue')")->fetch()['c']??0,'turnover'=>$db->query('SELECT COALESCE(SUM(amount),0) c FROM transactions WHERE status="approved"')->fetch()['c']??0];$winners=$db->query('SELECT w.*,f.name fund_name,CONCAT(u.first_name," ",u.last_name) winner_name FROM winners w JOIN funds f ON f.id=w.fund_id JOIN users u ON u.id=w.winner_user_id ORDER BY w.id DESC LIMIT 5')->fetchAll();$this->view('dashboard/index',compact('stats','winners')+['title'=>'داشبورد']);}}
